function initApp() {
L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
  attribution: "&copy; OpenStreetMap contributors"
}).addTo(map);

// Store all markers and route controls
var allMarkers = {};
var routeControls = {};
var animatedRoutes = {};
var activeDay = null;
var pulseIntervals = {};

// Create start marker (green flag)
function makeStartIcon(color, size) {
  size = size || 24;
  return L.divIcon({
    html: '<div class="marker-flag" style="color:' + color + ';width:' + size + 'px;height:' + size + 'px;display:flex;align-items:center;justify-content:center;z-index:1000;position:relative"><span class="flag-text" style="font-size:7px!important">START</span></div>',
    className: '',
    iconSize: [size, size],
    iconAnchor: [size/2, size/2],
    popupAnchor: [0, -size/2]
  });
}

// Create end marker (red flag)
function makeEndIcon(color, size) {
  size = size || 24;
  return L.divIcon({
    html: '<div class="marker-flag" style="color:' + color + ';width:' + size + 'px;height:' + size + 'px;display:flex;align-items:center;justify-content:center;z-index:999;position:relative"><span class="flag-text" style="font-size:7px!important">END</span></div>',
    className: '',
    iconSize: [size, size],
    iconAnchor: [size/2, size/2],
    popupAnchor: [0, -size/2]
  });
}

// Create numbered marker
function makeNumberIcon(color, num, size) {
  size = size || 24;
  var half = size / 2;
  return L.divIcon({
    html: '<div class="marker-circle" style="width:' + size + 'px;height:' + size + 'px;background:' + color + ';border-radius:50%;border:2px solid white;box-shadow:0 2px 6px rgba(0,0,0,.4);display:flex;align-items:center;justify-content:center;font-size:' + (size > 22 ? 11 : 9) + 'px;font-weight:700;color:white;text-shadow:0 1px 2px rgba(0,0,0,.4);line-height:1;user-select:none;position:relative">' + num + '</div>',
    className: '',
    iconSize: [size, size],
    iconAnchor: [half, half],
    popupAnchor: [0, -half]
  });
}

// Create inactive marker in day color but dimmed
function makeInactiveIcon(color, size) {
  size = size || 18;
  var half = size / 2;
  return L.divIcon({
    html: '<div style="width:' + size + 'px;height:' + size + 'px;background:' + color + ';border-radius:50%;border:2px solid rgba(255,255,255,0.8);box-shadow:0 1px 4px rgba(0,0,0,0.2);opacity:0.6"></div>',
    className: '',
    iconSize: [size, size],
    iconAnchor: [half, half],
    popupAnchor: [0, -half]
  });
}

// Animate marker appearance with bounce
function animateMarkerIn(marker, delay) {
  setTimeout(function() {
    var icon = marker.getIcon();
    if (icon && icon.element) {
      var circle = icon.element.querySelector('.marker-circle');
      if (circle) {
        circle.classList.add('bounce');
        setTimeout(function() { circle.classList.remove('bounce'); }, 600);
      }
      var flag = icon.element.querySelector('.marker-flag');
      if (flag) {
        flag.style.transform = 'scale(0)';
        flag.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
        setTimeout(function() { flag.style.transform = 'scale(1)'; }, 50);
        setTimeout(function() { flag.style.transform = ''; }, 450);
      }
    }
  }, delay);
}

// Bring start markers to front (for overlapping START/END)
function bringStartToFront(dayNum) {
  if (!allMarkers[dayNum]) return;
  var markers = allMarkers[dayNum];
  if (markers.length > 0) {
    markers[0].setZIndex(1000);
  }
  if (markers.length > 1) {
    markers[markers.length - 1].setZIndex(999);
  }
}

// Start pulsing animation on active markers
function startPulse(dayNum) {
  stopPulse();
  if (!allMarkers[dayNum]) return;
  allMarkers[dayNum].forEach(function(marker) {
    var icon = marker.getIcon();
    if (icon && icon.element) {
      var circle = icon.element.querySelector('.marker-circle');
      if (circle) circle.classList.add('pulse');
      var flag = icon.element.querySelector('.marker-flag');
      if (flag) {
        flag.style.animation = 'markerPulse 1.5s ease-in-out infinite';
      }
    }
  });
}

// Stop pulsing animation
function stopPulse() {
  Object.keys(pulseIntervals).forEach(function(day) {
    clearInterval(pulseIntervals[day]);
  });
  pulseIntervals = {};
}

// Add all markers for all days
DAYS.forEach(function(day) {
  allMarkers[day.num] = [];
  day.locs.forEach(function(loc, idx) {
    var lat = loc[0], lng = loc[1], name = loc[2], desc = loc[3], time = loc[4] || '';
    var marker = L.marker([lat, lng], { icon: makeInactiveIcon(day.color) })
      .addTo(map)
      .bindPopup('<b>' + name + '</b>' + (time ? '<div class="popup-time">' + time + '</div>' : '') + '<div class="popup-desc">' + desc + '</div><a href="https://www.google.com/maps/search/?api=1&query=' + lat + ',' + lng + '" target="_blank">View on Google Maps</a>');
    marker._seq = idx + 1;
    marker._total = day.locs.length;
    marker._time = time;
    marker._name = name;
    marker._desc = desc;
    marker._color = day.color;
    allMarkers[day.num].push(marker);
  });
});

// Update markers based on active day with staggered animation
function updateMarkers(dayNum, animate) {
  animate = animate !== false;
  var day = DAYS.find(function(d) { return d.num === dayNum; });
  var dayLocs = day ? day.locs : [];

  DAYS.forEach(function(d) {
    var isActive = (d.num === dayNum);
    allMarkers[d.num].forEach(function(marker, idx) {
      var icon;
      if (isActive) {
        var isFirst = idx === 0;
        var isLast = idx === dayLocs.length - 1;

        if (isFirst) {
          icon = makeStartIcon(d.color);
        } else if (isLast) {
          icon = makeEndIcon(d.color);
        } else {
          icon = makeNumberIcon(d.color, marker._seq);
        }
      } else {
        icon = makeInactiveIcon(d.color);
      }
      marker.setIcon(icon);
      marker.setPopupContent('<b>' + marker._name + '</b>' + (marker._time ? '<div class="popup-time">' + marker._time + '</div>' : '') + '<div class="popup-desc">' + marker._desc + '</div><a href="https://www.google.com/maps/search/?api=1&query=' + marker.getLatLng().lat + ',' + marker.getLatLng().lng + '" target="_blank">View on Google Maps</a>');

      if (isActive && animate) {
        animateMarkerIn(marker, idx * 80);
      }
    });
  });

  if (dayNum && day) {
    setTimeout(function() { startPulse(dayNum); }, day.locs.length * 80 + 200);
    setTimeout(function() { bringStartToFront(dayNum); }, day.locs.length * 80 + 500);
  }
}

// Animate route line being drawn
function animateRouteLine(dayNum, coords, color) {
  if (animatedRoutes[dayNum]) {
    map.removeLayer(animatedRoutes[dayNum]);
  }

  if (coords.length < 2) return;

  var animatedLine = L.polyline([], {
    color: color,
    weight: 5,
    opacity: 0.9,
    lineCap: 'round',
    lineJoin: 'round'
  }).addTo(map);

  animatedRoutes[dayNum] = animatedLine;

  var totalPoints = coords.length;
  var currentIdx = 0;
  var interval = setInterval(function() {
    currentIdx++;
    var points = coords.slice(0, currentIdx + 1);
    animatedLine.setLatLngs(points);

    if (currentIdx >= totalPoints - 1) {
      clearInterval(interval);
      addRouteArrows(dayNum, coords, color);
    }
  }, 8);
}

// Add directional arrows along the route
function addRouteArrows(dayNum, coords, color) {
  if (animatedRoutes[dayNum + '_arrows']) {
    map.removeLayer(animatedRoutes[dayNum + '_arrows']);
  }

  var arrow = L.polylineDecorator(animatedRoutes[dayNum], {
    patterns: [
      { offset: 0, repeat: 80, symbol: L.Symbol.arrowHead({ pixelSize: 10, polygon: true, headLength: 8, tailLength: 6, color: color, fillColor: color, fillOpacity: 1 }) }
    ]
  }).addTo(map);

  animatedRoutes[dayNum + '_arrows'] = arrow;
}

// Draw a route for a day using OSRM
function drawRoute(dayNum) {
  var day = DAYS.find(function(d) { return d.num === dayNum; });
  if (!day) return;

  if (routeControls[dayNum]) {
    map.removeControl(routeControls[dayNum]);
    routeControls[dayNum] = null;
  }
  if (animatedRoutes[dayNum]) {
    map.removeLayer(animatedRoutes[dayNum]);
    animatedRoutes[dayNum] = null;
  }
  if (animatedRoutes[dayNum + '_arrows']) {
    map.removeLayer(animatedRoutes[dayNum + '_arrows']);
    animatedRoutes[dayNum + '_arrows'] = null;
  }

  var locs = day.locs.map(function(l) { return L.latLng(l[0], l[1]); });

  var control = L.Routing.control({
    waypoints: locs,
    router: L.Routing.osrmv1({
      serviceUrl: 'https://router.project-osrm.org/route/v1',
      language: 'en'
    }),
    lineOptions: {
      styles: [{ color: day.color, weight: 5, opacity: 0, dashArray: null }],
      extendToWaypoints: true,
      missingRouteTolerance: 10
    },
    show: false,
    addWaypoints: false,
    fitSelectedRoutes: false,
    showAlternatives: false,
    collapsible: true,
    routeWhileDragging: false,
    waypointMode: 'stop'
  });

  control.on('routesfound', function(e) {
    var routes = e.routes;
    if (routes && routes.length > 0) {
      var coords = routes[0].coordinates;
      var totalDist = (routes[0].summary.totalDistance / 1000).toFixed(1);
      var totalTime = Math.round(routes[0].summary.totalTime / 60);
      setRouteStatus(dayNum, 'done', totalTime + ' min, ' + totalDist + ' km');
      animateRouteLine(dayNum, coords, day.color);
    }
  });

  control.on('routingerror', function(e) {
    setRouteStatus(dayNum, 'error', 'Route unavailable');
    var coords = day.locs.map(function(l) { return [l[0], l[1]]; });
    animateRouteLine(dayNum, coords, day.color);
  });

  control.addTo(map);
  routeControls[dayNum] = control;
  setRouteStatus(dayNum, 'loading', 'Routing...');
}

// Remove route for a day
function clearRoute(dayNum) {
  stopPulse();
  if (routeControls[dayNum]) {
    map.removeControl(routeControls[dayNum]);
    routeControls[dayNum] = null;
  }
  if (animatedRoutes[dayNum]) {
    map.removeLayer(animatedRoutes[dayNum]);
    animatedRoutes[dayNum] = null;
  }
  if (animatedRoutes[dayNum + '_arrows']) {
    map.removeLayer(animatedRoutes[dayNum + '_arrows']);
    animatedRoutes[dayNum + '_arrows'] = null;
  }
  setRouteStatus(dayNum, '', '');
}

// Set route status badge
function setRouteStatus(dayNum, cls, text) {
  var el = document.querySelector('.route-badge[data-day="' + dayNum + '"]');
  if (el) {
    el.className = 'route-badge' + (cls ? ' ' + cls : '');
    el.textContent = text;
  }
}

// Build day selector buttons
DAYS.forEach(function(day) {
  var btn = document.createElement('button');
  btn.className = 'day-btn';
  btn.setAttribute('data-day', day.num);
  btn.textContent = day.num + ' (' + (day.num === 1 ? '6/2' : day.num === 2 ? '6/3' : day.num === 3 ? '6/4' : day.num === 4 ? '6/5' : day.num === 5 ? '6/6' : day.num === 6 ? '6/7' : '6/8') + ')';
  btn.addEventListener('click', function() { selectDay(day.num); });
  document.getElementById('dayBtns').appendChild(btn);
});

// Build day cards
DAYS.forEach(function(day) {
  var card = document.createElement('div');
  card.className = 'day-card';
  card.setAttribute('data-day', day.num);
  card.style.color = day.border;

  var header = document.createElement('div');
  header.className = 'day-card-header';
  header.innerHTML =
    '<span class="day-num">' + day.num + ' (' + (day.num === 1 ? '6/2' : day.num === 2 ? '6/3' : day.num === 3 ? '6/4' : day.num === 4 ? '6/5' : day.num === 5 ? '6/6' : day.num === 6 ? '6/7' : '6/8') + ')</span>' +
    '<span class="day-title">' + day.title + '</span>' +
    '<span class="route-badge" data-day="' + day.num + '"></span>';

  var ul = document.createElement('ul');
  ul.className = 'loc-list';
  day.locs.forEach(function(loc, locIdx) {
    var li = document.createElement('li');
    var time = loc[4] ? '<span class="loc-time">' + loc[4] + '</span>' : '';
    li.innerHTML =
      '<span class="dot" style="background:' + day.color + '"></span>' +
      '<div><a href="https://www.google.com/maps/search/?api=1&query=' + loc[0] + ',' + loc[1] + '" target="_blank" class="loc-link" data-day="' + day.num + '" data-loc-idx="' + locIdx + '">' + loc[2] + '</a>' +
      '<span class="desc">' + loc[3] + '</span>' + time + '</div>';
    ul.appendChild(li);
  });

  card.appendChild(header);
  card.appendChild(ul);
  card.addEventListener('click', function() { selectDay(day.num); });
  document.getElementById('dayCards').appendChild(card);
});

// Day selection logic
function selectDay(dayNum) {
  if (activeDay === dayNum) {
    clearRoute(dayNum);
    updateMarkers(null, false);
    showAllMarkers();
    document.querySelectorAll('.day-card').forEach(function(c) { c.classList.remove('active'); });
    document.querySelectorAll('.day-btn').forEach(function(b) { b.classList.remove('active'); });
    activeDay = null;
    return;
  }

  if (activeDay !== null) {
    clearRoute(activeDay);
    updateMarkers(null, false);
    showAllMarkers();
  }

  activeDay = dayNum;
  var day = DAYS.find(function(d) { return d.num === dayNum; });

  hideOtherDayMarkers(dayNum);

  document.querySelectorAll('.day-card').forEach(function(c) {
    c.classList.toggle('active', parseInt(c.getAttribute('data-day')) === dayNum);
  });
  document.querySelectorAll('.day-btn').forEach(function(b) {
    b.classList.toggle('active', parseInt(b.getAttribute('data-day')) === dayNum);
  });

  updateMarkers(dayNum, true);
  drawRoute(dayNum);

  var dayMarkers = allMarkers[dayNum];
  if (dayMarkers.length > 0) {
    var group = L.featureGroup(dayMarkers);
    map.fitBounds(group.getBounds().pad(0.15));
  }
}

// Hide markers from days other than the specified day
function hideOtherDayMarkers(exceptDayNum) {
  DAYS.forEach(function(d) {
    if (d.num !== exceptDayNum) {
      allMarkers[d.num].forEach(function(marker) {
        marker.setOpacity(0);
      });
    }
  });
}

// Show all markers
function showAllMarkers() {
  DAYS.forEach(function(d) {
    allMarkers[d.num].forEach(function(marker) {
      marker.setOpacity(1);
    });
  });
}

// Click handler for location links - fly to marker but allow navigation
document.addEventListener('click', function(e) {
  if (e.target.classList.contains('loc-link')) {
    var dayNum = parseInt(e.target.getAttribute('data-day'));
    var locIdx = parseInt(e.target.getAttribute('data-loc-idx'));
    var marker = allMarkers[dayNum][locIdx];
    if (marker) {
      map.flyTo(marker.getLatLng(), 16, { animate: true, duration: 1 });
    }
  }
});

// Select day 1 by default
selectDay(1);

// Initialize MRT layers
initMRTLayers();
}

