    allMarkers[d.num].forEach(function(marker, idx) {
      var icon;
      if (isActive) {
        var isFirst = idx === 0;
        var isLast = idx === dayLocs.length - 1;

        if (isFirst) {
          icon = makeStartIcon(d.color);
        } else if (isLast) {
          icon = makeEndIcon(d.color);
        } else {
          icon = makeNumberIcon(d.color, marker._seq);
        }
      } else {
        icon = makeInactiveIcon(d.color);
      }
      marker.setIcon(icon);
      marker.setPopupContent('<b>' + marker._name + '</b>' + (marker._time ? '<div class="popup-time">' + marker._time + '</div>' : '') + '<div class="popup-desc">' + marker._desc + '</div><a href="https://www.google.com/maps/search/?api=1&query=' + marker.getLatLng().lat + ',' + marker.getLatLng().lng + '" target="_blank">View on Google Maps</a>');

      if (isActive && animate) {
        animateMarkerIn(marker, idx * 80);
      }
    });
  });

  if (dayNum && day) {
    setTimeout(function() { startPulse(dayNum); }, day.locs.length * 80 + 200);
    setTimeout(function() { bringStartToFront(dayNum); }, day.locs.length * 80 + 500);
  }
}

// Animate route line being drawn
function animateRouteLine(dayNum, coords, color) {
  if (animatedRoutes[dayNum]) {
    map.removeLayer(animatedRoutes[dayNum]);
  }

  if (coords.length < 2) return;

  var animatedLine = L.polyline([], {
    color: color,
    weight: 5,
    opacity: 0.9,
    lineCap: 'round',
    lineJoin: 'round'
  }).addTo(map);

  animatedRoutes[dayNum] = animatedLine;

  var totalPoints = coords.length;
  var currentIdx = 0;
  var interval = setInterval(function() {
    currentIdx++;
    var points = coords.slice(0, currentIdx + 1);
    animatedLine.setLatLngs(points);

    if (currentIdx >= totalPoints - 1) {
      clearInterval(interval);
      addRouteArrows(dayNum, coords, color);
    }
  }, 8);
}

// Add directional arrows along the route
function addRouteArrows(dayNum, coords, color) {
  if (animatedRoutes[dayNum + '_arrows']) {
    map.removeLayer(animatedRoutes[dayNum + '_arrows']);
  }

  var arrow = L.polylineDecorator(animatedRoutes[dayNum], {
    patterns: [
      { offset: 0, repeat: 80, symbol: L.Symbol.arrowHead({ pixelSize: 10, polygon: true, headLength: 8, tailLength: 6, color: color, fillColor: color, fillOpacity: 1 }) }
    ]
  }).addTo(map);

  animatedRoutes[dayNum + '_arrows'] = arrow;
}

// Draw a route for a day using OSRM
function drawRoute(dayNum) {
  var day = DAYS.find(function(d) { return d.num === dayNum; });
  if (!day) return;

  // Remove existing route for this day
  if (routeControls[dayNum]) {
    map.removeControl(routeControls[dayNum]);
    routeControls[dayNum] = null;
  }
  if (animatedRoutes[dayNum]) {
    map.removeLayer(animatedRoutes[dayNum]);
    animatedRoutes[dayNum] = null;
  }
  if (animatedRoutes[dayNum + '_arrows']) {
    map.removeLayer(animatedRoutes[dayNum + '_arrows']);
    animatedRoutes[dayNum + '_arrows'] = null;
  }

  var locs = day.locs.map(function(l) { return L.latLng(l[0], l[1]); });

  var control = L.Routing.control({
    waypoints: locs,
    router: L.Routing.osrmv1({
      serviceUrl: 'https://router.project-osrm.org/route/v1',
      language: 'en'
    }),
    lineOptions: {
      styles: [{ color: day.color, weight: 5, opacity: 0, dashArray: null }],
      extendToWaypoints: true,
      missingRouteTolerance: 10
    },
    show: false,
    addWaypoints: false,
    fitSelectedRoutes: false,
    showAlternatives: false,
    collapsible: true,
    routeWhileDragging: false,
    waypointMode: 'stop'
  });

  control.on('routesfound', function(e) {
    var routes = e.routes;
    if (routes && routes.length > 0) {
      var coords = routes[0].coordinates;
      var totalDist = (routes[0].summary.totalDistance / 1000).toFixed(1);
      var totalTime = Math.round(routes[0].summary.totalTime / 60);
      setRouteStatus(dayNum, 'done', totalTime + ' min, ' + totalDist + ' km');
      // Animate the route line
      animateRouteLine(dayNum, coords, day.color);
    }
  });

  control.on('routingerror', function(e) {
    setRouteStatus(dayNum, 'error', 'Route unavailable');
    // Fallback: draw straight lines with animation
    var coords = day.locs.map(function(l) { return [l[0], l[1]]; });
    animateRouteLine(dayNum, coords, day.color);
  });

  control.addTo(map);
  routeControls[dayNum] = control;
  setRouteStatus(dayNum, 'loading', 'Routing...');
}

// Remove route for a day
function clearRoute(dayNum) {
  stopPulse();
  if (routeControls[dayNum]) {
    map.removeControl(routeControls[dayNum]);
    routeControls[dayNum] = null;
