// Day selection logic
function selectDay(dayNum) {
  // Toggle off if already selected
  if (activeDay === dayNum) {
    clearRoute(dayNum);
    updateMarkers(null, false);
    showAllMarkers();
    document.querySelectorAll('.day-card').forEach(function(c) { c.classList.remove('active'); });
    document.querySelectorAll('.day-btn').forEach(function(b) { b.classList.remove('active'); });
    activeDay = null;
    return;
  }

  // Clear previous
  if (activeDay !== null) {
    clearRoute(activeDay);
    updateMarkers(null, false);
    showAllMarkers();
  }

  activeDay = dayNum;
  var day = DAYS.find(function(d) { return d.num === dayNum; });

  // Hide markers from other days
  hideOtherDayMarkers(dayNum);

  // Update UI
  document.querySelectorAll('.day-card').forEach(function(c) {
    c.classList.toggle('active', parseInt(c.getAttribute('data-day')) === dayNum);
  });
  document.querySelectorAll('.day-btn').forEach(function(b) {
    b.classList.toggle('active', parseInt(b.getAttribute('data-day')) === dayNum);
  });

  // Update markers with animation
  updateMarkers(dayNum, true);

  // Draw route
  drawRoute(dayNum);

  // Fit map to this day's markers
  var dayMarkers = allMarkers[dayNum];
  if (dayMarkers.length > 0) {
    var group = L.featureGroup(dayMarkers);
    map.fitBounds(group.getBounds().pad(0.15));
  }
}

// Hide markers from days other than the specified day
function hideOtherDayMarkers(exceptDayNum) {
  DAYS.forEach(function(d) {
    if (d.num !== exceptDayNum) {
      allMarkers[d.num].forEach(function(marker) {
        marker.setOpacity(0);
