// Create numbered marker
function makeNumberIcon(color, num, size) {
  size = size || 24;
  var half = size / 2;
  return L.divIcon({
    html: '<div class="marker-circle" style="width:' + size + 'px;height:' + size + 'px;background:' + color + ';border-radius:50%;border:2px solid white;box-shadow:0 2px 6px rgba(0,0,0,.4);display:flex;align-items:center;justify-content:center;font-size:' + (size > 22 ? 11 : 9) + 'px;font-weight:700;color:white;text-shadow:0 1px 2px rgba(0,0,0,.4);line-height:1;user-select:none;position:relative">' + num + '</div>',
    className: '',
    iconSize: [size, size],
    iconAnchor: [half, half],
    popupAnchor: [0, -half]
  });
}

// Create inactive marker in day color but dimmed
function makeInactiveIcon(color, size) {
  size = size || 18;
  var half = size / 2;
  return L.divIcon({
    html: '<div style="width:' + size + 'px;height:' + size + 'px;background:' + color + ';border-radius:50%;border:2px solid rgba(255,255,255,0.8);box-shadow:0 1px 4px rgba(0,0,0,0.2);opacity:0.6"></div>',
    className: '',
    iconSize: [size, size],
    iconAnchor: [half, half],
