// Animate marker appearance with bounce
function animateMarkerIn(marker, delay) {
  setTimeout(function() {
    var icon = marker.getIcon();
    if (icon && icon.element) {
      var circle = icon.element.querySelector('.marker-circle');
      if (circle) {
        circle.classList.add('bounce');
        setTimeout(function() { circle.classList.remove('bounce'); }, 600);
      }
      var flag = icon.element.querySelector('.marker-flag');
      if (flag) {
        flag.style.transform = 'scale(0)';
        flag.style.transition = 'transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)';
        setTimeout(function() { flag.style.transform = 'scale(1)'; }, 50);
        setTimeout(function() { flag.style.transform = ''; }, 450);
      }
    }
  }, delay);
}

// Bring start markers to front (for overlapping START/END)
function bringStartToFront(dayNum) {
  // Leaflet markers don't have bringToFront, using z-index instead
  if (!allMarkers[dayNum]) return;
  var markers = allMarkers[dayNum];
  if (markers.length > 0) {
    // First marker is always START, set higher z-index
    markers[0].setZIndex(1000);
  }
  if (markers.length > 1) {
    // Also ensure last marker (END) has lower z-index
    markers[markers.length - 1].setZIndex(999);
  }
}

// Start pulsing animation on active markers
function startPulse(dayNum) {
  stopPulse();
  if (!allMarkers[dayNum]) return;
  allMarkers[dayNum].forEach(function(marker) {
    var icon = marker.getIcon();
    if (icon && icon.element) {
      var circle = icon.element.querySelector('.marker-circle');
      if (circle) circle.classList.add('pulse');
      var flag = icon.element.querySelector('.marker-flag');
      if (flag) {
        flag.style.animation = 'markerPulse 1.5s ease-in-out infinite';
      }
    }
  });
}

// Stop pulsing animation
function stopPulse() {
  Object.keys(pulseIntervals).forEach(function(day) {
    clearInterval(pulseIntervals[day]);
  });
  pulseIntervals = {};
}

// Add all markers for all days
DAYS.forEach(function(day) {
  allMarkers[day.num] = [];
  day.locs.forEach(function(loc, idx) {
    var lat = loc[0], lng = loc[1], name = loc[2], desc = loc[3], time = loc[4] || '';
    var marker = L.marker([lat, lng], { icon: makeInactiveIcon(day.color) })
      .addTo(map)
      .bindPopup('<b>' + name + '</b>' + (time ? '<div class="popup-time">' + time + '</div>' : '') + '<div class="popup-desc">' + desc + '</div><a href="https://www.google.com/maps/search/?api=1&query=' + lat + ',' + lng + '" target="_blank">View on Google Maps</a>');
    marker._seq = idx + 1;
    marker._total = day.locs.length;
    marker._time = time;
    marker._name = name;
    marker._desc = desc;
    marker._color = day.color;
    allMarkers[day.num].push(marker);
  });
});

// Update markers based on active day with staggered animation
function updateMarkers(dayNum, animate) {
  animate = animate !== false;
  var day = DAYS.find(function(d) { return d.num === dayNum; });
