    allMarkers[d.num].forEach(function(marker, idx) {
      var icon;
      if (isActive) {
        var isFirst = idx === 0;
        var isLast = idx === dayLocs.length - 1;

        if (isFirst) {
          icon = makeStartIcon(d.color);
        } else if (isLast) {
          icon = makeEndIcon(d.color);
        } else {
          icon = makeNumberIcon(d.color, marker._seq);
        }
      } else {
        icon = makeInactiveIcon(d.color);
      }
      marker.setIcon(icon);
      marker.setPopupContent('<b>' + marker._name + '</b>' + (marker._time ? '<div class="popup-time">' + marker._time + '</div>' : '') + '<div class="popup-desc">' + marker._desc + '</div><a href="https://www.google.com/maps/search/?api=1&query=' + marker.getLatLng().lat + ',' + marker.getLatLng().lng + '" target="_blank">View on Google Maps</a>');

      if (isActive && animate) {
        animateMarkerIn(marker, idx * 80);
      }
    });
  });

  if (dayNum && day) {
    setTimeout(function() { startPulse(dayNum); }, day.locs.length * 80 + 200);
