var mrtLayers = {};
var mrtVisible = false;
var map;

function toggleMRT() {
  if (typeof map === 'undefined') return;
  var toggle = document.getElementById('mrtToggle');
  var legend = document.getElementById('mrtLegend');
  mrtVisible = !mrtVisible;
  if (mrtVisible) {
    toggle.classList.add('active');
    toggle.textContent = '🚇 Hide MRT Lines';
    legend.classList.add('show');
    Object.keys(mrtLayers).forEach(function(key) { map.addLayer(mrtLayers[key]); });
  } else {
    toggle.classList.remove('active');
    toggle.textContent = '🚇 Show MRT Lines';
    legend.classList.remove('show');
    Object.keys(mrtLayers).forEach(function(key) { map.removeLayer(mrtLayers[key]); });
  }
}

function initMRTLayers() {
  Object.keys(MRT_LINES).forEach(function(key) {
    var line = MRT_LINES[key];
    var polyline = L.polyline(line.coords, { color: line.color, weight: 4, opacity: 0.8 });
    mrtLayers[key] = polyline;
  });
}

